sys_script_client.script:
//MSSCUSTODY-7057 : Display Scrip Hold Indicator of Matching Trade on Form

function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    //Type appropriate comment here, and begin script below
    var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
    ga1.addParam('sysparm_name', 'getLinkTradeDetails');
    ga1.addParam('sysparm_transaction_reference', newValue);

    ga1.getXMLAnswer(function(response) {
        var res = JSON.parse(response);
        g_form.setValue('amend_script_hold_indicator', res.scripHold);
    });

}
